/* ========== 从 words.js 中提取现有 RAW_WORDS ========== */
function parseExisting() {
  const src = readFileSync(WORDS_JS, 'utf8');
  const rows = [];
  const re = /\["([^"]*)",\s*"([^"]*)",\s*"([^"]*)",\s*"([^"]*)",\s*"([^"]*)",\s*"([^"]*)"\]/g;
  let m;
  while ((m = re.exec(src))) {
    rows.push([m[1], m[2], m[3], m[4], m[5], m[6]]);
  }
  return rows;
}

